func (w *TableBitWriter) Put(value uint64, n int64) {
	if n < 0 || n > 64 {
		w.Overflow = true
		return
	}
	if n == 0 {
		return
	}
	at := w.Bits
	w.Bits += n
	if w.Bits < at {
		w.Overflow = true
		return
	}
	if w.Measuring {
		return
	}
	if (w.Bits+7)/8 > int64(len(w.Buffer)) {
		w.Overflow = true
		return
	}
	if n < 64 {
		value &= (uint64(1) << n) - 1
	}
	index := at >> 3
	shift := at & 7
	head := uint64(0)
	if shift != 0 {
		head = uint64(w.Buffer[index]) & ((uint64(1) << shift) - 1)
	}
	word := head | value<<shift
	need := (shift + n + 7) / 8
	if need >= 8 {
		binary.LittleEndian.PutUint64(w.Buffer[index:], word)
		if need > 8 {
			w.Buffer[index+8] = byte(value >> (64 - shift))
		}
	} else {
		for j := range need {
			w.Buffer[index+j] = byte(word >> (j * 8))
		}
	}
}
func (w *TableBitWriter) Align() { w.Put(0, (-w.Bits)&7) }
func (w *TableBitWriter) Raw(data []byte) {
	w.Align()
	if w.Measuring {
		w.Bits += int64(len(data)) * 8
		return
	}
	at := w.Bits / 8
	w.Bits += int64(len(data)) * 8
	if at > int64(len(w.Buffer))-int64(len(data)) {
		w.Overflow = true
		return
	}
	copy(w.Buffer[at:], data)
}
func (r *TableBitReader) Get(n int64) (uint64, bool) {
	if n < 0 || n > 64 || r.Offset < 0 || n > int64(len(r.Buffer))*8-r.Offset {
		return 0, false
	}
	if n == 0 {
		return 0, true
	}
	at := r.Offset >> 3
	shift := r.Offset & 7
	need := (shift + n + 7) / 8
	var value uint64
	if need >= 8 {
		value = binary.LittleEndian.Uint64(r.Buffer[at:]) >> shift
		if need > 8 {
			value |= uint64(r.Buffer[at+8]) << (64 - shift)
		}
	} else {
		for j := range need {
			value |= uint64(r.Buffer[at+j]) << (8 * j)
		}
		value >>= shift
	}
	if n < 64 {
		value &= (uint64(1) << n) - 1
	}
	r.Offset += n
	return value, true
}
func (r *TableBitReader) Skip(n int64) bool {
	if n < 0 || n > int64(len(r.Buffer))*8-r.Offset {
		return false
	}
	r.Offset += n
	return true
}
func (r *TableBitReader) Align() bool { v, ok := r.Get((-r.Offset) & 7); return ok && v == 0 }
func tableMessageBits(n uint64) int64 {
	var count int64
	for n != 0 {
		count++
		n >>= 1
	}
	return count
}

// Match the complete encoded entry once, while reading the announcement.
// Only the own slot is kept: no caller buffer is retained and no hash stands
// in for byte equality. One ID may have several distinct declared shapes.
func tableMessageOwnSlot(raw []byte) uint64 {
	for i, key := range tableMessageEntryKeys {
		if len(raw) != len(key) {
			continue
		}
		same := true
		for j := range raw {
			if raw[j] != key[j] {
				same = false
				break
			}
		}
		if same {
			return uint64(i + 1)
		}
	}
	return 0
}
func (v *TableVocabulary) Init(storage []TableMessageEntry) {
	*v = TableVocabulary{Entries: storage, MaxBytes: 64 * 1024}
}

// A FIELD ID TWICE IN ONE BODY IS DAMAGE (mas-bandwidth/schema docs/SPEC-TABLES.md §3.3), and the
// check is one test of the entry, in the caller's storage, whatever the
// vocabulary's size. Each body read takes the next tick of the vocabulary's
// clock and keeps it in starts[depth], an array the generated read declares
// at the unit's deepest nesting. An entry keeps the tick of its last naming
// (above eight bits holding that body's level, so the binary bound's deepest
// body fits) and a bit for each shallower level whose body had named it, in
// two words so every level below the binary bound has one: a level's mark
// still stands when that level's open body began at or before the last naming,
// and the levels whose bodies were opened since are dropped as the entry is
// named again. Two slots announcing one id are one entry, the first: the
// entries are sorted in place by id and position (the position parked in
// bodySeenAt, which every fresh entry holds at zero), each run of one id
// points at its first, and a second sort by position puts them back, so the
// work is n log n in the caller's storage and nothing is allocated.
func tableMessageSeenOpen(v *TableVocabulary, starts []uint64, depth int) {
	v.bodyClock++
	starts[depth] = v.bodyClock
	if depth == 0 {
		v.setTop = 0
	}
}
func tableMessageSeenFirst(v *TableVocabulary) {
	s := v.Entries[:v.Count]
	for i := range s {
		s[i].bodySeenAt = uint64(i)
		s[i].bodyFirst = 0
	}
	slices.SortFunc(s, func(a, b TableMessageEntry) int {
		v.announceProbes++
		if a.ID != b.ID {
			if a.ID < b.ID {
				return -1
			}
			return 1
		}
		if a.bodySeenAt < b.bodySeenAt {
			return -1
		}
		if a.bodySeenAt > b.bodySeenAt {
			return 1
		}
		return 0
	})
	for i := 1; i < len(s); i++ {
		if s[i].ID == s[i-1].ID {
			first := s[i-1].bodyFirst
			if first == 0 {
				first = s[i-1].bodySeenAt + 1
			}
			s[i].bodyFirst = first
		}
	}
	slices.SortFunc(s, func(a, b TableMessageEntry) int {
		v.announceProbes++
		if a.bodySeenAt < b.bodySeenAt {
			return -1
		}
		if a.bodySeenAt > b.bodySeenAt {
			return 1
		}
		return 0
	})
	for i := range s {
		s[i].bodySeenAt = 0
	}
}
func tableMessageSeenRepeat(v *TableVocabulary, starts []uint64, depth int, ref uint64) bool {
	e := &v.Entries[ref-1]
	if e.bodyFirst != 0 {
		e = &v.Entries[e.bodyFirst-1]
	}
	at, last := e.bodySeenAt>>8, int(e.bodySeenAt&255)
	if starts[depth] <= at {
		if last == depth || depth < 128 && e.bodySeenBelow[depth>>6]>>uint(depth&63)&1 != 0 {
			return true
		}
		if depth < 64 {
			e.bodySeenBelow[0] &= 1<<uint(depth) - 1
			e.bodySeenBelow[1] = 0
		} else if depth < 128 {
			e.bodySeenBelow[1] &= 1<<uint(depth-64) - 1
		}
	} else {
		kept, hi := 0, depth
		for kept < hi {
			mid := (kept + hi) / 2
			if starts[mid] <= at {
				kept = mid + 1
			} else {
				hi = mid
			}
		}
		if last < kept {
			e.bodySeenBelow[last>>6] |= 1 << uint(last&63)
		}
		if kept < 64 {
			e.bodySeenBelow[0] &= 1<<uint(kept) - 1
			e.bodySeenBelow[1] = 0
		} else if kept < 128 {
			e.bodySeenBelow[1] &= 1<<uint(kept-64) - 1
		}
	}
	e.bodySeenAt = v.bodyClock<<8 | uint64(depth)
	return false
}

// A KEY TWICE IN ONE KEYED ARRAY AND A FIELD ID TWICE IN ONE SKIPPED BODY ARE
// DAMAGE (mas-bandwidth/schema docs/SPEC-TABLES.md §3.2, §3.3), and each test is one look at the
// named entry, as the body's is: no scan of the keys seen so far, and nothing
// allocated. Every keyed array and every skipped body is a SET on one stack in
// the vocabulary, opened at the next clock tick; an entry keeps the tick and
// level of its last naming and a bit for each shallower set that had named it
// and is still open, so a set's marks survive the sets nested inside it. Two
// slots announcing one id are one entry, the first. The root body's open
// empties the stack, so a refused read leaves nothing behind.
func tableMessageSetOpen(v *TableVocabulary) int {
	if v.setTop >= len(v.setStarts)-1 {
		return -1
	}
	v.setTop++
	v.bodyClock++
	v.setStarts[v.setTop] = v.bodyClock
	return v.setTop
}
func tableMessageSetClose(v *TableVocabulary) {
	if v.setTop > 0 {
		v.setTop--
	}
}
func tableMessageSetRepeat(v *TableVocabulary, level int, ref uint64) bool {
	v.setProbes++
	e := &v.Entries[ref-1]
	if e.bodyFirst != 0 {
		e = &v.Entries[e.bodyFirst-1]
	}
	at, last := e.setSeenAt>>9, int(e.setSeenAt&511)
	starts := v.setStarts[:level+1]
	if starts[level] <= at {
		if last == level || e.setSeenBelow[level>>6]>>uint(level&63)&1 != 0 {
			return true
		}
		tableMessageSetTrim(&e.setSeenBelow, level)
	} else {
		kept, hi := 0, level
		for kept < hi {
			mid := (kept + hi) / 2
			v.setProbes++
			if starts[mid] <= at {
				kept = mid + 1
			} else {
				hi = mid
			}
		}
		if last < kept {
			e.setSeenBelow[last>>6] |= 1 << uint(last&63)
		}
		tableMessageSetTrim(&e.setSeenBelow, kept)
	}
	e.setSeenAt = v.bodyClock<<9 | uint64(level)
	return false
}
func tableMessageSetTrim(b *[5]uint64, k int) {
	for i := range b {
		lo := i * 64
		if k <= lo {
			b[i] = 0
		} else if k < lo+64 {
			b[i] &= 1<<uint(k-lo) - 1
		}
	}
}
func (v *TableVocabulary) Entry(ref uint64) (TableMessageEntry, bool) {
	if ref == 0 || ref > uint64(v.Count) {
		return TableMessageEntry{}, false
	}
	return v.Entries[ref-1], true
}
func (v *TableVocabulary) Name(ref uint64) (uint64, bool) {
	e, ok := v.Entry(ref)
	return e.ID, ok && e.Shape.Kind == 0 && e.ID < 0xfffffffffffffffd
}
func tableMessageNameSlot(id uint64) uint64 {
	for i := range tableMessageEntries {
		e := &tableMessageEntries[i]
		if e.ID == id && e.Shape.Kind == 0 {
			return uint64(i + 1)
		}
	}
	return 0
}
func AnnounceMeasure() int64 { return int64(len(tableAnnouncement)) }
func Announce(buffer []byte) int64 {
	if len(buffer) < len(tableAnnouncement) {
		return -1
	}
	copy(buffer, tableAnnouncement[:])
	return int64(len(tableAnnouncement))
}
func tableMessageRefuse(r *TableReport, reason string) bool {
	r.Verdict = TableOpenRefused
	r.FixedRaised = false
	r.Reason = reason
	return false
}
func AnnounceRead(v *TableVocabulary, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	if v.Announced || v.Refused {
		return tableMessageRefuse(report, "second_announcement")
	}
	ok := tableAnnounceRead(v, data, report)
	if !ok {
		v.Refused = true
	}
	return ok
}
func tableAnnounceRead(v *TableVocabulary, data []byte, report *TableReport) bool {
	r, verdict := tableOpenFramed(data, report)
	if verdict != TableOpenOk {
		if verdict == TableOpenRefused {
			reason := "newer_form"
			if len(data) > 0 && data[0] == 2 {
				reason = "message_form_as_file"
			}
			return tableMessageRefuse(report, reason)
		}
		report.Refuse(TableRefuseWireDamaged, "")
		return false
	}
	versionCount, wordsCount := 0, 0
	var words []byte
	var seen [4097]bool
	var fuRep TableReport
	tableFirstUseCount(&fuRep, 2)
	r.Report = &fuRep
	for {
		ref, ok := r.Leb()
		if !ok {
			report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		if ref == 0 {
			break
		}
		if ref > 4096 || seen[ref] {
			report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		seen[ref] = true
		id, ok := r.Resolve(ref)
		if !ok || !r.Has(1) || id == 0xffffffffffffffff {
			report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		kind := r.Get8()
		switch id {
		case 0xfffffffffffffffe:
			if kind != 9 || !r.Has(8) {
				report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			v.BuildVersion = r.Get64()
			versionCount++
		case 0xfffffffffffffffd:
			if kind != 14 {
				report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			sub, ok := r.Body()
			if !ok || !sub.Has(1) || sub.Get8() != 6 {
				report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			n, ok := sub.Leb()
			if !ok || n > uint64(len(sub.Buffer)) || int64(n) != int64(len(sub.Buffer))-sub.Offset {
				report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			limit := v.MaxBytes
			if limit == 0 {
				limit = 64 * 1024
			}
			if int64(n) > limit {
				return tableMessageRefuse(report, "vocabulary_too_large")
			}
			words = sub.Buffer[sub.Offset:]
			wordsCount++
		default:
			report.Unknown++
			var wc tableWireCheck
			wc.ids = uint64(len(r.Ids)) / 8
			at, wok := wc.value(r, kind)
			if !wok {
				report.Refuse(wc.failed(), "")
				return false
			}
			r.Offset = at
		}
	}
	if r.Offset != int64(len(r.Buffer)) || !tableFirstUseWhole(&fuRep, uint64(len(r.Ids))/8) || versionCount != 1 || wordsCount != 1 {
		report.Refuse(TableRefuseWireDamaged, "")
		return false
	}
	if v.Strict && v.BuildVersion != BuildVersion {
		report.BuildVersionRemote = v.BuildVersion
		report.BuildVersionOwn = BuildVersion
		return tableMessageRefuse(report, "build_version_mismatch")
	}
	src := TableReader{Buffer: words, Report: report}
	count := int64(0)
	nodeSeen := false
	twice := func(s []TableMessageEntry) bool {
		slices.SortFunc(s, func(a, b TableMessageEntry) int {
			return slices.Compare(words[a.Shape.Min:a.Shape.Max], words[b.Shape.Min:b.Shape.Max])
		})
		for i := 1; i < len(s); i++ {
			if slices.Equal(words[s[i-1].Shape.Min:s[i-1].Shape.Max], words[s[i].Shape.Min:s[i].Shape.Max]) {
				return true
			}
		}
		return false
	}
	for src.Offset < int64(len(words)) {
		if count >= int64(len(v.Entries)) {
			if twice(v.Entries[:count]) {
				report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			return tableMessageRefuse(report, "vocabulary_too_large")
		}
		began := src.Offset
		e, ok := tableMessageEntryRead(&src)
		if !ok || e.ID == 0xfffffffffffffffd || e.ID == 0xfffffffffffffffe || e.ID == 0xffffffffffffffff && nodeSeen {
			report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		if e.ID == 0xffffffffffffffff {
			nodeSeen = true
		}
		e.Shape.Min = began
		e.Shape.Max = src.Offset
		v.Entries[count] = e
		count++
	}
	if twice(v.Entries[:count]) {
		report.Refuse(TableRefuseWireDamaged, "")
		return false
	}
	src.Offset = 0
	for i := range count {
		began := src.Offset
		e, ok := tableMessageEntryRead(&src)
		if !ok {
			report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		e.OwnSlot = tableMessageOwnSlot(words[began:src.Offset])
		v.Entries[i] = e
	}
	v.Count = count
	v.RefBits = tableMessageBits(uint64(count))
	if v.RefBits == 0 {
		v.RefBits = 1
	}
	tableMessageSeenFirst(v)
	v.Announced = true
	return true
}

// THE SHAPE IS THE DECLARED ONE, the bytes the announcement spells, and never
// the resolved entry: a resolved quantized entry keeps §4.3's derivation and
// not the max and res it consumed, so two declared shapes that derive one delta
// and count would read as one entry there, and a legitimate announcement, the
// unit's own included, would be refused as malformed (#722). Go's == on float32
// also equates +0 and -0, whose declared bytes differ. The entry's encoding is
// canonical, a minimal LEB128 and fixed four-byte floats, so byte equality is
// declared-fact equality, bit pattern for bit pattern. Each accepted entry parks
// its byte extent in Shape.Min and Shape.Max until the scan is over, and the
// second pass in tableAnnounceRead resolves every entry in place, so no offset
// into the announcement outlives the call. The duplicate test sorts the
// parked extents in place by their bytes and compares neighbours (twice), so
// it is n log n in the entry count, allocates nothing, and leaves the order to
// the second pass, which rewrites every entry from the announcement. It runs
// when the entries are all read, and also before vocabulary_too_large, so a
// repeated entry read before the bound is crossed is damage, as it was when
// each entry was compared on arrival. It is spelled inline so the emitter
// claims no new runtime name.
// tableMessageKnownKind is §3.3's closed announcement set: kinds 0..32 plus the
// timestamp 36 (mas-bandwidth/schema docs/SPEC-TABLES.md §3.3 entry shape table); 33, 34, 35 and 37
// stay malformed.
func tableMessageKnownKind(k uint8) bool { return k <= 32 || k == 36 }
func tableMessageKindBits(k uint8) int64 {
	if k == 0 || k == 32 {
		return 0
	}
	if k == 1 {
		return 1
	}
	switch k {
	case 2, 6, 20, 25:
		return 8
	case 3, 7, 21, 26:
		return 16
	case 4, 8, 10, 22, 27:
		return 32
	case 5, 9, 11, 23, 28, 36:
		return 64
	case 18, 19, 24, 29:
		return 128
	}
	return -1
}
func tableMessageBaseInsideKind(k uint8, b [2]uint64) bool {
	switch k {
	case 18, 19, 24, 29:
		return true
	case 2, 3, 4:
		w := uint(tableMessageKindBits(k))
		lo := -(int64(1) << (w - 1))
		hi := (int64(1) << (w - 1)) - 1
		v := int64(b[0])
		return v >= lo && v <= hi
	case 6, 7, 8:
		w := uint(tableMessageKindBits(k))
		return b[0] <= (uint64(1)<<w)-1
	case 5, 9:
		return true
	case 20, 21, 22, 23:
		v := int64(b[0])
		wantHi := uint64(0)
		if v < 0 {
			wantHi = ^uint64(0)
		}
		if b[1] != wantHi {
			return false
		}
		if k == 23 {
			return true
		}
		w := uint(tableMessageKindBits(k))
		lo := -(int64(1) << (w - 1))
		hi := (int64(1) << (w - 1)) - 1
		return v >= lo && v <= hi
	case 25, 26, 27, 28:
		if b[1] != 0 {
			return false
		}
		if k == 28 {
			return true
		}
		w := uint(tableMessageKindBits(k))
		return b[0] <= (uint64(1)<<w)-1
	}
	return true
}
func tableMessageShapeRead(r *TableReader, k uint8) (s TableMessageShape, ok bool) {
	s.Kind = k
	s.Bits = tableMessageKindBits(k)
	switch {
	case k >= 2 && k <= 10 || k >= 18 && k <= 29:
		if !r.Has(1) {
			return s, false
		}
		s.Packing = r.Get8()
		if s.Packing == 0 {
			return s, true
		}
		if s.Packing == 1 && k != 10 {
			n, ok := r.Leb()
			if !ok || n > uint64(s.Bits) {
				return s, false
			}
			s.Bits = int64(n)
			if k >= 18 {
				if !r.Has(16) {
					return s, false
				}
				s.Base = [2]uint64{r.Get64(), r.Get64()}
			} else {
				base, ok := r.Leb()
				if !ok {
					return s, false
				}
				if k >= 2 && k <= 5 {
					base = uint64(int64(base>>1) ^ -int64(base&1))
				}
				s.Base[0] = base
			}
			if !tableMessageBaseInsideKind(k, s.Base) {
				return s, false
			}
			return s, true
		}
		if s.Packing == 2 && k == 10 {
			if !r.Has(12) {
				return s, false
			}
			lo := math.Float32frombits(r.Get32())
			hi := math.Float32frombits(r.Get32())
			res := math.Float32frombits(r.Get32())
			if !(lo < hi) || !(res > 0) {
				return s, false
			}
			delta := float32(hi - lo)
			values := float32(delta / res)
			if delta-delta != 0 || values-values != 0 {
				return s, false
			}
			if !(values >= 1) {
				values = 1
			} else if values > 4294967040.0 {
				values = 4294967040.0
			}
			s.QMin = lo
			s.QDelta = delta
			s.QCount = uint32(math.Ceil(float64(values)))
			s.Bits = tableMessageBits(uint64(s.QCount))
			return s, true
		}
		return s, false
	case k == 12:
		n, ok := r.Leb()
		if !ok || n > math.MaxInt32 {
			return s, false
		}
		s.Max = int64(n)
	case k == 14 || k == 16:
		if k == 14 {
			n, ok := r.Leb()
			if !ok || n > math.MaxUint32 {
				return s, false
			}
			s.Min = int64(n)
		}
		n, ok := r.Leb()
		if !ok || n > math.MaxUint32 || int64(n) < s.Min {
			return s, false
		}
		s.Max = int64(n)
	}
	return s, true
}
func tableMessageEntryRead(r *TableReader) (e TableMessageEntry, ok bool) {
	if !r.Has(9) {
		return e, false
	}
	e.ID = r.Get64()
	kind := r.Get8()
	if !tableMessageKnownKind(kind) {
		return e, false
	}
	e.Shape, ok = tableMessageShapeRead(r, kind)
	if !ok {
		return e, false
	}
	if kind == 14 || kind == 16 {
		if !r.Has(1) {
			return e, false
		}
		elem := r.Get8()
		if !tableMessageKnownKind(elem) || elem == 14 || elem == 16 {
			return e, false
		}
		e.Element, ok = tableMessageShapeRead(r, elem)
		if !ok {
			return e, false
		}
	}
	return e, true
}
func tableMessageCount(r *TableBitReader, s TableMessageShape) (uint64, bool) {
	raw, ok := r.Get(tableMessageBits(uint64(s.Max - s.Min)))
	return raw + uint64(s.Min), ok
}

// tableMessageOverMax is a count past the ANNOUNCED max, which its bits can
// spell and no conforming writer emits (mas-bandwidth/schema docs/SPEC-TABLES.md §3.3); a read
// shape's max is never negative, and the guard says so.
func tableMessageOverMax(n uint64, s TableMessageShape) bool { return s.Max < 0 || n > uint64(s.Max) }

// field is set where the payload is a FIELD's own, an unknown field of a body:
// a conforming writer elides a None union field, so an explicit arm reference
// 0 there is refused (mas-bandwidth/schema docs/SPEC-TABLES.md §3.3), while an array element's and a
// union arm value's None stay positional and lawful.
func tableMessageSkip(r *TableBitReader, v *TableVocabulary, indexBits int64, e TableMessageEntry, depth int, field bool) bool {
	if depth > 128 {
		return false
	}
	s := e.Shape
	switch s.Kind {
	case 0, 32:
		return true
	case 30:
		ref, ok := r.Get(v.RefBits)
		if !ok || ref == 0 {
			return ok
		}
		_, ok = v.Name(ref)
		return ok
	case 13:
		return tableMessageSkipBody(r, v, indexBits, depth+1)
	case 17:
		return indexBits > 0 && r.Skip(indexBits)
	case 15:
		ref, ok := r.Get(v.RefBits)
		if !ok || ref == 0 {
			return ok && !field
		}
		arm, ok := v.Entry(ref)
		return ok && arm.ID < 0xfffffffffffffffd && arm.Shape.Kind != 0 && tableMessageSkip(r, v, indexBits, arm, depth+1, false)
	case 12:
		n, ok := tableMessageCount(r, s)
		if !ok || n > uint64(s.Max) || !r.Align() {
			return false
		}
		start := r.Offset / 8
		if !r.Skip(int64(n) * 8) {
			return false
		}
		return tableUTF8Valid(r.Buffer[start : start+int64(n)])
	case 31:
		if !r.Align() {
			return false
		}
		n, ok := r.Get(32)
		return ok && r.Skip(int64(n)*8)
	case 14, 16:
		n, ok := tableMessageCount(r, s)
		if !ok || n > uint64(s.Max) {
			return false
		}
		if s.Kind == 14 && e.Element.Kind == 6 && !r.Align() {
			return false
		}
		// a RANGED element carries a value condition, base plus offset inside its
		// announced kind, so it is walked as a float is, unless it rides no bits
		if s.Kind == 14 && (e.Element.Bits >= 0 && e.Element.Kind != 10 && e.Element.Kind != 11 && (e.Element.Packing != 1 || e.Element.Bits == 0) || e.Element.Kind == 0 || e.Element.Kind == 32) {
			width := max(e.Element.Bits, int64(0))
			return r.Skip(int64(n) * width)
		}
		if s.Kind == 16 {
			level := tableMessageSetOpen(v)
			if level < 0 {
				return false
			}
			for range n {
				ref, ok := r.Get(v.RefBits)
				if !ok {
					return false
				}
				if _, ok = v.Name(ref); !ok || tableMessageSetRepeat(v, level, ref) {
					return false
				}
				if !tableMessageSkip(r, v, indexBits, TableMessageEntry{Shape: e.Element}, depth+1, false) {
					return false
				}
			}
			tableMessageSetClose(v)
			return true
		}
		for range n {
			before := r.Offset
			if !tableMessageSkip(r, v, indexBits, TableMessageEntry{Shape: e.Element}, depth+1, false) || r.Offset == before {
				return false
			}
		}
		return true
	case 10:
		if s.Packing == 2 {
			index, ok := r.Get(s.Bits)
			return ok && index <= uint64(s.QCount)
		}
		raw, ok := r.Get(32)
		if !ok {
			return false
		}
		f := math.Float32frombits(uint32(raw))
		return f == f && !math.IsInf(float64(f), 0)
	case 11:
		raw, ok := r.Get(64)
		if !ok {
			return false
		}
		f := math.Float64frombits(raw)
		return !math.IsNaN(f) && !math.IsInf(f, 0)
	}
	// A RANGED INTEGER IS RECONSTRUCTED AND HELD TO ITS ANNOUNCED KIND on the
	// skip path too (mas-bandwidth/schema docs/SPEC-TABLES.md §3.3), by the one reconstruction the
	// typed read uses, so a body gets one verdict named or skipped
	if s.Packing == 1 {
		var raw [16]byte
		ok, over := tableMessageReadScalar(r, s, &raw)
		return ok && !over
	}
	return s.Bits >= 0 && r.Skip(s.Bits)
}

// Framing scans follow announced shapes; typed body reads diagnose reserved ids.
func tableMessageSkipBody(r *TableBitReader, v *TableVocabulary, indexBits int64, depth int) bool {
	if depth > 128 {
		return false
	}
	level := tableMessageSetOpen(v)
	if level < 0 {
		return false
	}
	for {
		ref, ok := r.Get(v.RefBits)
		if !ok {
			return false
		}
		if ref == 0 {
			tableMessageSetClose(v)
			return true
		}
		e, ok := v.Entry(ref)
		if !ok || e.ID >= 0xfffffffffffffffd || tableMessageSetRepeat(v, level, ref) {
			return false
		}
		if !tableMessageSkip(r, v, indexBits, e, depth, true) {
			return false
		}
	}
}

// Numeric values are reconstructed at the announced storage width. Typed
// readers then hold these lanes to the declared ranges, as the file read does.
// The reconstruction is canonical: a signed kind is sign-extended to 128 bits,
// an unsigned kind zero-extended, and a ranged offset carries into the high
// lane. A timestamp (kind 36) is a signed sixty-four bit count. A value past
// the 128-bit domain of an integer kind is reported so the reader refuses it
// before it narrows.
func tableMessageReadScalar(r *TableBitReader, s TableMessageShape, out *[16]byte) (bool, bool) {
	integer := s.Kind >= 2 && s.Kind <= 9 || s.Kind >= 18 && s.Kind <= 29 || s.Kind == 36
	signed := integer && (s.Kind <= 5 || s.Kind == 18 || s.Kind >= 20 && s.Kind <= 24 || s.Kind == 36)
	lo, ok := r.Get(min(s.Bits, 64))
	if !ok || s.Packing == 2 && lo > uint64(s.QCount) {
		return false, false
	}
	hi := uint64(0)
	if s.Bits > 64 {
		hi, ok = r.Get(s.Bits - 64)
		if !ok {
			return false, false
		}
	}
	if s.Packing == 1 {
		baseHi := s.Base[1]
		if signed && s.Kind < 18 {
			baseHi = uint64(int64(s.Base[0]) >> 63)
		}
		loSum := lo + s.Base[0]
		carry := uint64(0)
		if loSum < lo {
			carry = 1
		}
		hiSum := hi + baseHi
		carryHi := uint64(0)
		if hiSum < hi {
			carryHi = 1
		}
		hiSum += carry
		if hiSum < carry {
			carryHi = 1
		}
		if integer {
			if signed {
				if baseHi>>63 == 0 {
					if carryHi != 0 || hiSum>>63 != 0 {
						return true, true
					}
				} else {
					mLo := ^s.Base[0] + 1
					mHi := ^baseHi
					if mLo == 0 {
						mHi++
					}
					borrow := uint64(0)
					if lo < mLo {
						borrow = 1
					}
					dHi := hi - mHi - borrow
					if !(hi < mHi || hi == mHi && borrow != 0) && dHi>>63 != 0 {
						return true, true
					}
				}
			} else if carryHi != 0 {
				return true, true
			}
		}
		lo = loSum
		hi = hiSum
		// THE ANNOUNCED KIND HOLDS THE SUM OR THE READ REFUSES (mas-bandwidth/schema docs/SPEC-TABLES.md
		// §3.3), whatever the reader's own kind: uint8 | min = 200, max = 250
		// spells 200 + 63 in six bits, and a widened uint16 reader must not land it
		if integer {
			if w := tableMessageKindBits(s.Kind); w < 128 {
				if signed {
					if int64(hi) != int64(lo)>>63 || w < 64 && (int64(lo) < -(int64(1)<<uint(w-1)) || int64(lo) > (int64(1)<<uint(w-1))-1) {
						return true, true
					}
				} else if hi != 0 || w < 64 && lo>>uint(w) != 0 {
					return true, true
				}
			}
		}
	} else if signed {
		if s.Bits < 64 {
			if s.Bits > 0 {
				shift := uint(64 - s.Bits)
				lo = uint64(int64(lo<<shift) >> shift)
			}
			hi = uint64(int64(lo) >> 63)
		} else if s.Bits == 64 {
			hi = uint64(int64(lo) >> 63)
		} else if s.Bits < 128 {
			shift := uint(64 - (s.Bits - 64))
			hi = uint64(int64(hi<<shift) >> shift)
		}
	}
	if s.Packing == 2 {
		index := uint32(lo)
		ratio := float32(float32(index) / float32(s.QCount))
		scaled := float32(ratio * s.QDelta)
		lo = uint64(math.Float32bits(float32(scaled + s.QMin)))
	}
	binary.LittleEndian.PutUint64(out[:], lo)
	binary.LittleEndian.PutUint64(out[8:], hi)
	return true, false
}

// A quantized float outside its range is a value the writer refuses
// (mas-bandwidth/schema docs/SPEC-TABLES.md §3.3): over counts it, and the save answers -1. So is a
// ranged value whose offset from its base does not fit its bits, a flags bit
// past the declared W among them: a writer never truncates (§5).
func tableMessageWriteScalar(w *TableBitWriter, over *int32, s TableMessageShape, lo, hi uint64) {
	if s.Packing == 1 {
		borrow := uint64(0)
		if lo < s.Base[0] {
			borrow = 1
		}
		lo -= s.Base[0]
		hi -= s.Base[1] + borrow
		if s.Kind >= 18 {
			if s.Bits < 64 && (hi != 0 || lo>>uint(s.Bits) != 0) || s.Bits >= 64 && s.Bits < 128 && hi>>uint(s.Bits-64) != 0 {
				*over++
			}
		} else if s.Bits < 64 && lo>>uint(s.Bits) != 0 {
			*over++
		}
	}
	if s.Packing == 2 {
		value := math.Float32frombits(uint32(lo))
		ratio := float32((value - s.QMin) / s.QDelta)
		if !(ratio >= 0) {
			ratio = 0
			*over++
		} else if !(ratio <= 1) {
			ratio = 1
			*over++
		}
		scaled := float32(ratio * float32(s.QCount))
		lo = uint64(min(uint32(math.Floor(float64(float32(scaled+0.5)))), s.QCount))
	}
	w.Put(lo, min(s.Bits, 64))
	if s.Bits > 64 {
		w.Put(hi, s.Bits-64)
	}
}
func tableMessageBatchOpen(v *TableVocabulary, data []byte, report *TableReport) (TableMessageReader, int64) {
	r := TableMessageReader{Vocabulary: v, Report: *report}
	defer func() { *report = r.Report }()
	if len(data) == 0 {
		r.Report.Refuse(TableRefuseWireDamaged, "")
		return r, -1
	}
	if data[0] != 2 {
		tableMessageRefuse(&r.Report, "newer_form")
		return r, -1
	}
	if v == nil || !v.Announced {
		tableMessageRefuse(&r.Report, "no_vocabulary")
		return r, -1
	}
	if len(data) < 2 {
		r.Report.Refuse(TableRefuseWireDamaged, "")
		return r, -1
	}
	r.Bits.Buffer = data[2:]
	return r, int64(data[1]) + 1
}
func tableMessageBatchClose(r *TableMessageReader) bool {
	if !r.Bits.Align() || r.Bits.Offset != int64(len(r.Bits.Buffer))*8 {
		r.Report.Refuse(TableRefuseWireDamaged, "")
		return false
	}
	return true
}
