	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !TableMixedSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	if w.Over != 0 {
		if report != nil {
			report.Refuse(TableRefuseInvalidValue, "")
		}
		return -1
	}
	return 2 + w.Bits/8
