	need := TableMixedMeasureMessages(values, report)
	if need < 0 || int64(len(buffer)) < need {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !TableMixedSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	if w.Over != 0 {
		if report != nil {
			report.Refuse(TableRefuseInvalidValue, "")
		}
		return -1
	}
	return 2 + w.Bits/8
